/// <summary>
/// Bug 381900: [MS]- E2E - Customer - Demand - Customer attribute changes did not flow to Sorted- SR#2606020030002567
/// </summary>
[ExtensionOf(tableStr(EcoResValue))]
final class METEcoResValueTbl_Extension
{
}

Method.Source:
/// <summary>
/// After customer attribute is updated, update new field against customer master to trigger data event.
/// </summary>
public void update()
{
    next update();

    this.metUpdateMETCustTable();
    this.updateArttibutesCacheValue();
}

/// <summary>
/// After customer attribute is updated, update new field against customer master to trigger data event.
/// </summary>
public void insert()
{
    next insert();

    this.metUpdateMETCustTable();
    this.updateArttibutesCacheValue();
}

/// <summary>
/// When an attribute is created or updated, this method will update the METCustTable to trigger the data event for downstream system to consume.
/// </summary>
public void metUpdateMETCustTable()
{
    ttsbegin;
    METCustTable metCustTable;
    CustTable custTable;
    CustomerInstanceValue customerInstanceValue;
    EcoResAttributeValue    EcoResAttributeValue;

    select firstonly forupdate metCustTable
        exists join custTable
            where custTable.AccountNum == metCustTable.AccountNum
        exists join customerInstanceValue
            where customerInstanceValue.AccountNum == custTable.AccountNum
        exists join EcoResAttributeValue
            where EcoResAttributeValue.InstanceValue == customerInstanceValue.RecId
                && EcoResAttributeValue.Value == this.RecId;

    if (metCustTable)
    {
        metCustTable.DataEventDateTime = DateTimeUtil::utcNow();
        metCustTable.update();
    }

    ttscommit;
}

/// <summary>
/// Loads the attribute-value record that references this value and, if the attribute
/// matches a configured product-level attribute (GST exempt, levy type, invoice category, or priced-by-weight),
/// refreshes the cached attribute values for the related product.
/// </summary>
public void updateArttibutesCacheValue()
{
    METGetAttributeValue        getAttributeValue;
    EcoResProductParameters     ecoResProductParameters = EcoResProductParameters::find();
    EcoResAttributeValue        EcoResAttributeValue;
    InventTable                 inventTable;
    RecId                       productRecId;

    select firstonly EcoResAttributeValue
        where EcoResAttributeValue.Value == this.RecId;

    if (EcoResAttributeValue 
            && (EcoResAttributeValue.Attribute == ecoResProductParameters.METConsumerGSTExempt
                || EcoResAttributeValue.Attribute == ecoResProductParameters.METLevyType
                || EcoResAttributeValue.Attribute == ecoResProductParameters.METInvoiceCategory
                || EcoResAttributeValue.Attribute == ecoResProductParameters.METPricedByWeight
                || EcoResAttributeValue.Attribute == ecoResProductParameters.METTempItemForPackChange))
    {
        productRecId = EcoResProductInstanceValue::find(EcoResAttributeValue.InstanceValue).Product;

        if (!productRecId)
        {
            return;
        }

        inventTable = InventTable::findByProduct(productRecId);
        if (!inventTable.RecId)
        {
            return;
        }

        ttsbegin;
        getAttributeValue = METGetAttributeValue::newFromInventTable(inventTable);
        getAttributeValue.setAttributeValues(ecoResProductParameters);
        ttscommit;
    }
}
